mockMvc.perform(get("/.well-known/security.txt")).andExpect(status().isOk()).andDo(r -> {
  String body = r.getResponse().getContentAsString();
  String exp = body.lines().filter(l -> l.startsWith("Expires:")).findFirst().orElseThrow().substring(8).trim();
  assertThat(Instant.parse(exp)).isAfter(Instant.now());
});
